parameters.jsCode:
const value = $json.body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];

// Ignore status updates and anything that isn't a text message
if (!msg || msg.type !== 'text') {
  return [];
}

return [{
  json: {
    from: msg.from,                              // guest's phone number
    text: msg.text.body,                         // what they wrote
    name: value.contacts?.[0]?.profile?.name,    // their WhatsApp name
    message_id: msg.id
  }
}];

